<script setup lang="ts">
import { createExportController } from '~/utils/export-controller'
import { createExportBlobSaver } from '~/utils/export-download'
const props=defineProps<{ scenarioId:string; revisionId:string; version:number; disabled?:boolean; autoOpen?:boolean }>(),auth=useAuthStore(),open=ref(false)
const context=()=>({user:auth.user?.id??'',school:auth.tenant?.school_id??'',scenario:props.scenarioId,revision:props.revisionId,version:props.version})
const saver=createExportBlobSaver(),ctrl=createExportController(useExportApi({...context()}),context,{getItem:key=>localStorage.getItem(key),setItem:(key,value)=>localStorage.setItem(key,value)},saver.save)
const {format,receipt,snapshot,history,job,error,pending,pause,gate,activeEntry,storageBlocked,downloaded}=ctrl
const newAllowed=computed(()=>!!receipt.value?.jobId&&history.value.some(e=>e.id===receipt.value?.jobId&&['ready','failed'].includes(e.status)))
function visibility(){ctrl.setVisible(!document.hidden&&open.value)}
watch(open,value=>{if(value){visibility();void ctrl.open()}else{ctrl.reset();saver.clear()}})
watch(()=>[auth.user?.id,auth.tenant?.school_id,props.revisionId,props.version],()=>{open.value=false;ctrl.reset();saver.clear()},{flush:'sync'})
onMounted(()=>{document.addEventListener('visibilitychange',visibility);if(props.autoOpen)open.value=true})
watch(()=>props.autoOpen,value=>{if(value)open.value=true})
onBeforeUnmount(()=>{document.removeEventListener('visibilitychange',visibility);ctrl.reset();saver.clear()})
</script>
<template><div class="export-entry"><UiButton variant="secondary" @click="open=true"><img src="/icons/fe008/download.svg" width="17" height="17" alt="">Экспорт и история</UiButton><UiModal v-model="open" title="Экспорт сценария"><div class="export-workspace"><p class="muted">Версия {{ version }} · документы формируются сервером</p><UiAlert v-if="error" tone="error"><strong>{{ error.message }}</strong><p>Проверьте состояние документа и условия допуска. Новое задание автоматически не создаётся.</p></UiAlert><UiAlert v-if="gate || disabled" tone="warning">{{ disabled?'Сначала сохраните изменения и завершите действие в редакторе.':gate }}</UiAlert><NuxtLink v-if="gate || error" :to="`/scenarios/${scenarioId}/edit`" @click="open=false">Перейти к проверке и согласованию</NuxtLink><UiState v-if="pending==='history' && !snapshot" kind="loading" title="Загружаем ревизию, модерацию и историю" /><template v-if="snapshot"><p class="muted">P0: {{ snapshot.verification.p0 }} · P1: {{ snapshot.verification.p1 }}. При изменении источников потребуется повторная проверка и подтверждение. Доступность экспорта проверяется заново.</p><ExportFormatPicker :model-value="format" :disabled="!!pending" @update:model-value="ctrl.select" /><UiAlert v-if="receipt?.phase==='uncertain'" tone="warning">Результат запуска неизвестен. Обновите историю; при восстановлении будет использован тот же ключ. Другой ключ автоматически не создаётся.</UiAlert><div class="export-actions"><UiButton :disabled="!!pending || !!gate || disabled || storageBlocked" :loading="pending==='create'" @click="ctrl.create(false)">{{ receipt?.phase==='accepted'?'Открыть созданное задание':receipt?.phase==='uncertain'?'Восстановить с прежним ключом':'Создать экспорт' }}</UiButton><UiButton v-if="newAllowed" variant="secondary" :disabled="!!pending || !!gate || disabled || storageBlocked" @click="ctrl.create(true)">Создать новый файл этого формата</UiButton></div><ExportJobState v-if="job" :job="job" :entry="activeEntry" :busy="!!pending" :read-error="error?.message" :pause="pause" @download="ctrl.download" @refresh="ctrl.resume" /><p v-if="downloaded" role="status">Документ передан браузеру для сохранения: {{ downloaded }}</p><ExportHistory :entries="history" :version="version" :busy="!!pending" @refresh="ctrl.refresh" @show="ctrl.show" @download="ctrl.download" /></template><UiButton v-if="!snapshot && !pending" @click="ctrl.open">Перечитать данные</UiButton><p class="muted">Закрытие окна останавливает наблюдение в этой вкладке. Уже принятое сервером задание продолжает выполняться.</p></div></UiModal></div></template>
